fn filter_vowels_array(xs: &[char]) -> Vec<char> {
    // Define the set of lowercase English vowels.
    const VOWELS: [char; 5] = ['a', 'e', 'i', 'o', 'u'];

    // Create a new dynamic array to hold the filtered result.
    let mut ys = Vec::new();

    // Iterate over the input slice and push only vowels into `ys`.
    for &c in xs {
        if VOWELS.contains(&c) {
            ys.push(c);
        }
    }

    ys
}

